    (if m = 0 then (0, 0, 0)
      else
        have sign := if m > 0 then 1 else -1;
        have mAbs := m.natAbs;
        have nDigits := Lean.JsonNumber.countDigits✝ mAbs;
        do
        let __s ←
          forIn (*...nDigits) mAbs fun x __s =>
              have mAbs := __s;
              if mAbs % 10 = 0 then
                have mAbs := mAbs / 10;
                pure (ForInStep.yield mAbs)
              else pure (ForInStep.done mAbs)
        have mAbs : ℕ := __s
