  | { mantissa := m, exponent := 0 } => m.repr
  | { mantissa := m, exponent := e } =>
    have sign := if m ≥ 0 then "" else "-";
    have m := m.natAbs;
    have exp := 9 + ↑(Lean.JsonNumber.countDigits✝ m) - ↑e;
    have exp := if exp < 0 then exp else 0;
    have e' := 10 ^ (e - exp.natAbs);
    have left := (m / e').repr;
    if (decide (m % e' = 0) && decide (exp = 0)) = true then toString sign ++ toString left
    else
      have right :=
        (((e' + m % e').repr.toRawSubstring.drop 1).dropRightWhile fun c =>
            decide (c = '0')).toString;
      have exp := if exp = 0 then "" else "e" ++ exp.repr;
      toString sign ++ toString left ++ toString "." ++ toString right ++ toString exp

